  add("Factors, multiples, primes, divisibility and order of operations.","Faktor, gandaan, nombor perdana, kebolehbahagian dan tertib operasi.","因数、倍数、质数、整除性与运算顺序。","約数、倍数、素数、割り切れる条件、演算順序。","약수, 배수, 소수, 나눗셈 성질, 연산 순서.");
  add("Fractions and calculations with unlike denominators.","Pecahan dan pengiraan dengan penyebut berlainan.","分数与异分母计算。","分母が異なる分数の計算。","분모가 다른 분수 계산.");
  add("Decimals, percentages and percentage change.","Perpuluhan, peratus dan perubahan peratus.","小数、百分比与百分比变化。","小数、百分率、割合の変化。","소수, 백분율, 백분율 변화.");
  add("Assessment using numerical reasoning and real-world problems.","Penilaian menggunakan penaakulan nombor dan masalah dunia sebenar.","使用数值推理与现实问题进行评估。","数的推論と実生活問題による評価。","수리 추론과 실생활 문제를 활용한 평가.");
  add("Algebraic notation, simplifying expressions and substitution.","Notasi algebra, memudahkan ungkapan dan substitution.","代数表示、化简表达式与代入。","代数表記、式の整理、代入。","대수 표기, 식 정리, 대입.");
  add("Equations, sequences and mathematical rules.","Persamaan, jujukan dan peraturan matematik.","方程、数列与数学规律。","方程式、数列、数学的な規則。","방정식, 수열, 수학적 규칙.");
  add("Angles, polygons, perimeter, area and volume.","Sudut, poligon, perimeter, luas dan isipadu.","角、多边形、周长、面积与体积。","角、多角形、周囲、面積、体積。","각도, 다각형, 둘레, 넓이, 부피.");
  add("Assessment combining algebra and geometry.","Penilaian menggabungkan algebra dan geometri.","结合代数与几何的评估。","代数と図形を組み合わせた評価。","대수와 기하를 결합한 평가.");
  add("Ratio, proportion, rates and scale.","Nisbah, kadar banding, kadar dan skala.","比、比例、率与比例尺。","比、比例、割合、縮尺。","비, 비례, 비율, 축척.");
  add("Mean, median, mode, range, charts and graphs.","Min, median, mod, julat, carta dan graf.","平均数、中位数、众数、极差、图表与图形。","平均、中央値、最頻値、範囲、グラフ。","평균, 중앙값, 최빈값, 범위, 차트와 그래프.");
  add("Non-routine multi-step problems and explaining reasoning.","Masalah bukan rutin berbilang langkah dan menerangkan penaakulan.","非常规多步骤问题与推理说明。","非定型の多段階問題と考え方の説明。","비정형 다단계 문제와 풀이 과정 설명.");
